                "reasoning": {"effort": "low"},
                "text": {"format": (
                    {"type": "json_schema", "name": role, "strict": True, "schema": schema}
                    if schema else {"type": "json_object"}
                )},
                "max_output_tokens": 4096,
                "store": False,
            }
            if self.chatgpt:
                result = stream_response(self.client, self.chatgpt, payload, remaining, record)
            else:
                response = bounded_post(
                    "https://api.openai.com/v1/responses",
                    deadline=call_deadline, transport=self.transport,
                    headers={"Authorization": "Bearer " + self.review_key},
                    json=payload,
                )
                record["http_status"] = response.status_code
                if response.is_error:
                    try:
                        error = response.json().get("error", {})
                        for field in ("code", "type", "param"):
                            value = error.get(field)
                            if isinstance(value, str) and re.fullmatch(r"[a-z_.]{1,80}", value):
                                record["error_" + field] = value
                    except (ValueError, AttributeError):
                        pass
                response.raise_for_status()
                result = response.json()
            record["usage"] = result.get("usage", {})
            if deadline_now() >= call_deadline:
                raise httpx.ReadTimeout("Model response arrived after its deadline")
            if result.get("status") != "completed":
                raise ValueError("incomplete Astra response")
            chunks = []
            for item in result.get("output", []):
                if item.get("type") != "message":
                    continue
                for part in item.get("content", []):
                    if part.get("type") == "refusal":
                        raise ValueError("Astra declined review")
                    if part.get("type") == "output_text":
                        chunks.append(part["text"])
            obj = decode_conditions(parse_object("".join(chunks)))
            record["status"] = "ok"
            return obj
        except Exception as exc:
